const onChange: ChangeHandler = async (event) => {
  _state.mount = true;
  const target = event.target;
  let name: string = target.name;
  let isFieldValueUpdated = true;
  const field: Field = get(_fields, name);
  const _updateIsFieldValueUpdated = (fieldValue: unknown) => {
    isFieldValueUpdated =
      Number.isNaN(fieldValue) ||
      (isDateObject(fieldValue) && isNaN(fieldValue.getTime())) ||
      deepEqual(fieldValue, get(_formValues, name, fieldValue));
  };

  if (field) {
    let error;
    let isValid;
    const fieldValue = target.type
      ? getFieldValue(field._f)
      : getEventValue(event);
    const isBlurEvent =
      event.type === EVENTS.BLUR || event.type === EVENTS.FOCUS_OUT;
    const hasNoValidationEffect =
      !hasValidation(field._f) &&
      !props.validate &&
      !_options.resolver &&
      !get(_formState.errors, name) &&
      !field._f.deps;
    const shouldSkipValidation =
      hasNoValidationEffect ||
      skipValidation(
        isBlurEvent,
        get(_formState.touchedFields, name),
        _formState.isSubmitted,
        _validationModeAfterSubmit,
        _validationModeBeforeSubmit,
      );
    const watched = isWatched(name, _names, isBlurEvent);

    set(_formValues, name, fieldValue);

    if (isBlurEvent) {
      if (!target || !target.readOnly) {
        field._f.onBlur && field._f.onBlur(event);
        const pendingDelayError = delayErrorCallbacks[name];
        pendingDelayError && pendingDelayError(0);
      }
    } else if (field._f.onChange) {
      field._f.onChange(event);
    }

    const fieldState = updateTouchAndDirty(name, fieldValue, isBlurEvent);

    const shouldRender = !isEmptyObject(fieldState) || watched;

    !isBlurEvent &&
      _subjects.state.next({
        name,
        type: event.type,
        ...(_valuesSubscriberCount
          ? { values: cloneObject(_formValues) }
          : {}),
      });

    if (shouldSkipValidation) {
      if (
        (!hasNoValidationEffect || !_formState.isValid) &&
        (_proxyFormState.isValid || _proxySubscribeFormState.isValid)
      ) {
        if (_options.mode === 'onBlur') {
          if (isBlurEvent) {
            _setValid();
          }
        } else if (!isBlurEvent) {
          _setValid();
        }
      }

      return (
        shouldRender &&
        _subjects.state.next({ name, ...(watched ? {} : fieldState) })
      );
    }

    if (!_options.resolver && props.validate) {
      await validateForm({
        name: name as FieldPath<TFieldValues>,
        eventType: event.type,
      });
    }

    !isBlurEvent && watched && _subjects.state.next({ ..._formState });

    if (_options.resolver) {
      const { errors } = await _runSchema([name]);
      _updateIsValidating([name]);

      _updateIsFieldValueUpdated(fieldValue);

      if (!isFieldValueUpdated) {
        !isEmptyObject(fieldState) && _subjects.state.next(fieldState);
        return;
      }

      const previousErrorLookupResult = schemaErrorLookup(
        _formState.errors,
        _fields,
        name,
      );
      const errorLookupResult = schemaErrorLookup(
        errors,
        _fields,
        previousErrorLookupResult.name || name,
      );

      error = errorLookupResult.error;
      name = errorLookupResult.name;

      isValid = isEmptyObject(errors);
    } else {
      _updateIsValidating([name], true);
      error = (
        await validateField(
          field,
          _names.disabled,
          _formValues,
          shouldDisplayAllAssociatedErrors,
          _options.shouldUseNativeValidation,
        )
      )[name];
      _updateIsValidating([name]);

      _updateIsFieldValueUpdated(fieldValue);

      if (isFieldValueUpdated) {
        if (error) {
          isValid = false;
        } else if (
          _proxyFormState.isValid ||
          _proxySubscribeFormState.isValid
        ) {
          isValid = await executeBuiltInValidation({
            fields: _fields,
            onlyCheckValid: true,
            name: name as FieldPath<TFieldValues>,
            eventType: event.type,
          });
        }
      }
    }

    if (isFieldValueUpdated) {
      field._f.deps &&
        (!Array.isArray(field._f.deps) || field._f.deps.length > 0) &&
        trigger(
          field._f.deps as
            | FieldPath<TFieldValues>
            | FieldPath<TFieldValues>[],
        );
      shouldRenderByError(name, isValid, error, fieldState);
    }
  }
};

const _focusInput = (ref: Ref, key: string) => {
  if (get(_formState.errors, key) && ref.focus) {
    ref.focus();
    return 1;
  }
